create policy "public read desktop downloads" on storage.objects for select to anon, authenticated using (bucket_id = 'desktop-downloads');
create policy "admins upload desktop downloads" on storage.objects for insert to authenticated with check (bucket_id = 'desktop-downloads' and public.has_role(auth.uid(),'admin'));
create policy "admins update desktop downloads" on storage.objects for update to authenticated using (bucket_id = 'desktop-downloads' and public.has_role(auth.uid(),'admin'));
create policy "admins delete desktop downloads" on storage.objects for delete to authenticated using (bucket_id = 'desktop-downloads' and public.has_role(auth.uid(),'admin'));